export const RECIPE_CANONICALS = {
  "{\"name\":\"simple honey garlic chicken\",\"ingredients\":[\"Chicken thighs (or breasts)\",\"Salt\",\"Pepper\",\"Oil\",\"Few cloves of garlic, chopped\",\"2 tablespoons honey\",\"Splash of soy sauce\",\"Water\",\"Chili flakes (optional)\",\"Broccoli (optional)\"],\"instructions\":[\"Season the chicken with salt and pepper and sear in a pan with oil until browned on both sides.\",\"Remove chicken from the pan. Add chopped garlic and sauté for 30 seconds until fragrant.\",\"Add honey, soy sauce, and a splash of water to the pan and stir until bubbling.\",\"Return the chicken to the pan, spoon the sauce over it, and simmer for about 10 minutes or until cooked through and sauce has thickened.\",\"Add water if the sauce becomes too sticky and serve over rice.\"],\"yield\":\"null\",\"groups\":[],\"times\":[5,15,20]}": "69c5ca7b97c98f58f25055c8",
  "{\"name\":\"buffalo chicken stuffed shells\",\"ingredients\":[\"20 jumbo pasta shells\",\"3 cups cooked, shredded chicken\",\"1 cup ricotta cheese\",\"3/4 cup buffalo sauce\",\"1 cup shredded mozzarella cheese, divided\",\"1/2 cup shredded cheddar cheese\",\"2 green onions, chopped\",\"1/2 cup ranch or blue cheese dressing\",\"Salt and pepper to taste\"],\"instructions\":[\"Cook pasta shells according to package instructions; drain and set aside.\",\"In a large bowl, mix shredded chicken, ricotta, buffalo sauce, 1/2 cup mozzarella, cheddar, green onions, and ranch dressing. Season with salt and pepper.\",\"Stuff each shell with the chicken mixture and place in a greased 9x13-inch baking dish. Top with remaining 1/2 cup mozzarella.\",\"Bake at 375°F for 25 minutes or until bubbly. Garnish with extra green onions and a drizzle of ranch.\"],\"yield\":\"\",\"groups\":[],\"times\":[0,25,25]}": "69dbf872c8bb01e598e6ca5f",
  "{\"name\":\"pork chops with aubergine\",\"ingredients\":[\"1 tbsp olive oil\",\"1medium aubergine cut into small cubes\",\"1 tbsp balsamic vinegar\",\"1 tsp sugar\",\"400g can chopped tomatoes with garlic\",\"handful basil leaves torn\",\"4 boneless pork chops\"],\"instructions\":[\"Heat the oil in a large saucepan, tip in the aubergine then fry over a medium heat for 5 mins until soft and golden. Pour in the vinegar. Once the bubbling subsides, stir in the sugar, followed by the tomatoes, basil and seasoning to taste. Stir well and cook over high heat for 5 mins, until the sauce has thickened.\",\"Meanwhile, heat the grill to medium and season the pork. Place the chops under the grill for 15 mins, turning halfway, until golden and cooked through. Serve the chops with the aubergines on the side.\"],\"yield\":\"\",\"groups\":[],\"times\":[5,25,30]}": "69dd78d52a03163328445016",
  "{\"name\":\"thai chicken soup\",\"ingredients\":[\"140g soba or wholewheat noodles\",\"100g beansprouts\",\"2 pak choi leaves separated\",\"1 red chilli deseeded and sliced\",\"1 tbsp soy sauce\",\"2 tbsp honey\",\"juice 1 lime plus wedges to serve\",\"4 spring onions sliced\",\"&frac12; small bunch mint roughly chopped\",\"1 roast chicken carcass and wings\",\"thumb-sized piece ginger bashed and sliced\",\"1 garlic clove crushed\",\"2 spring onions sliced\",\"5 peppercorns\"],\"instructions\":[\"To make the broth, place the chicken carcass and wings in a large pan. Cover with cold water, then add the rest of the ingredients and simmer for 1 hr.\",\"Strain the chicken broth into a clean pan. Carefully pick out any pieces of chicken and return to the broth. Put the broth back on the heat and bring back to the boil.\",\"Add the noodles and cook for 3 mins until tender, then stir in the beansprouts, pak choi, red chilli, soy sauce, honey and lime juice, adding the squeezed lime halves to the pot, too. Can be frozen at this point. Cook for 2 mins more. Ladle the soup into bowls, scatter over the spring onions and mint leaves, and serve with the lime wedges for squeezing over.\"],\"yield\":\"Serves 4\",\"groups\":[],\"times\":[10,90,100]}": "69e96ecd2a03163328447d86",
  "{\"name\":\"grandmother's chicken paprikash\",\"ingredients\":[\"1.5kg chicken pieces, bone-in\",\"2 large onions, finely diced\",\"3 tbsp sweet Hungarian paprika\",\"1 tsp hot paprika\",\"400ml chicken stock\",\"200ml sour cream\",\"2 tbsp vegetable oil\",\"Salt and pepper\",\"Fresh dill to finish\"],\"instructions\":[\"Season chicken well. Brown in batches in hot oil. Set aside.\",\"Cook onions in the same pot over low heat until very soft, about 15 mins.\",\"Remove from heat. Stir in both paprikas — off heat prevents burning.\",\"Return chicken. Add stock. Simmer covered 40 mins until cooked through.\",\"Remove chicken. Stir sour cream into sauce over low heat — don't boil.\",\"Return chicken. Serve over egg noodles or spätzle with dill.\"],\"yield\":\"4 servings\",\"groups\":[],\"times\":[20,60,80]}": "6a03440281f294c08ab1b492",
  "{\"name\":\"pasta with hazelnut pesto and asparagus\",\"ingredients\":[\"1 garlic clove, roughly chopped\",\"pinch salt\",\"60g/21⁄4oz fresh basil leaves\",\"50g/13⁄4oz hazelnuts, toasted, plus extra to serve (optional) – see recipe tips\",\"30g/1oz plant-based hard cheese (or regular Parmesan for a non-vegetarian recipe), grated, plus extra to serve (optional)\",\"25g/1oz nutritional yeast\",\"125ml/4fl oz good-quality extra virgin olive oil, plus extra to serve (optional)\",\"1 large preserved lemon, finely grated zest only\",\"large bunch asparagus, woody stems removed and thinly sliced lengthways\",\"200g/7oz long dried pasta, such as linguine, spaghetti or tagliatelle\",\"salt\"],\"instructions\":[\"To make the pesto, use either a pestle and mortar or a blender or food processor.\",\"If using a pestle and mortar to make the pesto, add the garlic and salt and pound to a smooth paste. Add the basil a handful at a time and bruise gently rather than smashing. Work in the hazelnuts and pound until coarse but well combined. Fold in the cheese and nutritional yeast. Slowly drizzle in the oil while turning the pestle until the mixture is a loose pesto-like consistency. Stir through the preserved lemon zest.\",\"If using a food processor or blender to make the pesto, blend the garlic, salt, basil, hazelnuts, cheese, nutritional yeast and half of the oil in a food processor or blender. Add the remaining oil and blend again until there is a loose but still textured pesto-like mixture. Stir through the preserved lemon zest.\",\"To make the asparagus, bring a large saucepan of heavily salted water to the boil. Cook the asparagus for 1 minute, or until just tender. Transfer the asparagus to a bowl using tongs or a slotted spoon, reserving the cooking water in the pan.\",\"To make the pasta, add the pasta to the same cooking water and cook until al dente (cooked but still firm when bitten). Reserve a mug of the pasta cooking water then drain.\",\"Return the drained pasta to the pan. Add the pesto, asparagus and a splash of pasta water. Toss gently over a low heat until glossy and well coated. Add more pasta water if needed to loosen.\",\"Divide the pasta mixture between bowls and finish with a sprinkling of cheese, a drizzle of oil and a scattering of hazelnuts, if using.\"],\"yield\":\"Serves 2\",\"groups\":[],\"times\":[30,30,60]}": "6a05c32f6adf56093b9e6e84",
  "{\"name\":\"dad's fried rice\",\"ingredients\":[\"600g cold cooked jasmine rice (day-old is essential)\",\"3 eggs, beaten\",\"150g char siu or cooked ham, diced small\",\"100g frozen peas\",\"4 spring onions, sliced\",\"3 cloves garlic, minced\",\"3 tbsp neutral oil\",\"2 tbsp light soy sauce\",\"1 tbsp oyster sauce\",\"1 tsp sesame oil\",\"White pepper\"],\"instructions\":[\"Heat wok over highest heat until smoking. Add 1 tbsp oil.\",\"Pour in eggs. Scramble quickly, just barely set. Remove and set aside.\",\"Add remaining oil. Fry garlic 30 seconds.\",\"Add rice. Press and toss constantly for 3–4 mins until each grain is separate.\",\"Add soy sauce and oyster sauce. Toss to coat evenly.\",\"Add peas, char siu and eggs. Toss 1 minute.\",\"Finish with sesame oil, spring onions and white pepper.\"],\"yield\":\"4 servings\",\"groups\":[],\"times\":[10,15,25]}": "6a0601d96adf56093b9e6f95",
  "{\"name\":\"green harissa eggs\",\"ingredients\":[\"Green harissa: 1 bunch coriander, 1 bunch parsley, 2 green chillies, 2 cloves garlic, 1 tsp cumin, 3 tbsp olive oil, juice of 1 lemon, salt\",\"4 eggs\",\"1 tin chickpeas, drained\",\"1 tbsp olive oil\",\"Greek yoghurt to serve\"],\"instructions\":[\"Blend all harissa ingredients until a rough paste. Taste and adjust.\",\"Warm chickpeas in olive oil in a wide pan over medium heat, 3 mins.\",\"Stir through 3 tbsp of harissa. Let it bubble and coat.\",\"Make wells. Crack in eggs. Cover and cook 5–6 mins until whites are just set.\",\"Serve with yoghurt and extra harissa.\"],\"yield\":\"2 servings\",\"groups\":[],\"times\":[10,15,25]}": "6a0b63a36adf56093b9e94a5",
  "{\"name\":\"cilantro lime chicken and lentil rice bowls\",\"ingredients\":[\"2 cups dried lentils\",\"1 lb. boneless skinless chicken breasts (or chicken thighs)\",\"3 cups salsa verde\",\"3 cups chicken broth\",\"1/2 small onion, chopped\",\"3 green onions, chopped\",\"1/2 cup cilantro, chopped\",\"3 cloves garlic, minced\",\"2 jalapeños, diced (ribs and seeds removed)\",\"1/2 teaspoon salt, plus more to taste\",\"1-2 limes\"],\"instructions\":[\"Add everything to the Instant Pot except the lime juice.\",\"Cook for 30 minutes on Soup setting. Quick release the steam. Stir it all up and add more salsa verde as desired.\",\"Serve with rice and a squeeze of lime!\"],\"yield\":\"8\",\"groups\":[],\"times\":[15,30,45]}": "6a0fb11e6adf56093b9ea04d",
  "{\"name\":\"mushroom and spinach lasagne\",\"ingredients\":[\"6–8 sheets dried lasagne\",\"2 tbsp olive oil\",\"1 large onion, roughly chopped\",\"500g/1lb 2oz button mushrooms, sliced\",\"2 large garlic cloves, finely grated\",\"30g/1oz plain flour\",\"2 x 400g tins chopped tomatoes\",\"1 tbsp freshly chopped thyme leaves\",\"2 tsp balsamic vinegar\",\"2 tbsp sun-dried tomato paste\",\"200g/7oz baby spinach, trimmed\",\"55g/2oz unsalted butter\",\"55g/2oz plain flour\",\"600ml/1 pint hot milk\",\"2 tbsp Dijon mustard\",\"150g/5oz mature cheddar, coarsely grated\",\"55g/2oz Parmesan (or alternative vegetarian hard cheese), coarsely grated\",\"salt and freshly ground black pepper\"],\"instructions\":[\"Soak the lasagne sheets in hot water for 15 minutes to soften. Drain and refresh under cold water, then drain again.\",\"Preheat the oven to 200C/180C Fan/Gas 6. You will need a 2.25-litre/4-pint rectangular ovenproof dish.\",\"Heat the oil in a large non-stick frying pan over a high heat. Add the onion and fry for a few minutes. Add the mushrooms and garlic and fry for 3–4 minutes, stirring, to drive off any excess liquid.\",\"Sprinkle in the flour and mix well. Add the tomatoes, thyme, vinegar, tomato paste and spinach. Fry over a high heat for a further 3–5 minutes, or until the spinach has wilted and the sauce is bubbling. Season with salt and freshly ground black pepper, then remove from the heat and set aside.\",\"To make the cheese sauce, melt the butter in a saucepan over a medium heat. Stir in the flour, then whisk in the hot milk. Add the mustard and two-thirds of the cheeses. Season, then bring to the boil, whisking for a few minutes, until thickened.\",\"To assemble the lasagne, spoon a third of the mushroom and tomato sauce into the base of the dish. Top with a third of the cheese sauce, then place half the lasagne sheets in a single layer on top.\",\"Repeat the layers until you have three layers of mushroom and tomato sauce, three layers of cheese sauce and two layers of pasta. Sprinkle with the remaining cheeses.\",\"Bake for about 40 minutes, or until golden brown, bubbling around the edges and the pasta is tender.\"],\"yield\":\"Serves 6\",\"groups\":[],\"times\":[30,60,90]}": "6a1c8bc56adf56093b9edd26",
  "{\"name\":\"key lime pie\",\"ingredients\":[\"3 egg yolks\",\"1 tin condensed milk\",\"2 Tbs lime zest\",\"1/2 c. lime juice\"],\"instructions\":[\"Beat the egg yolks until fluffy.\",\"Slowly add the condensed milk and beat for 5 minutes.\",\"Add the lime zest and then slowly add the lime juice until well mixed.\",\"Pour the mixture into a baked biscuit crust.\",\"Bake at 175 degrees for 10-15 minutes.\",\"Let it cool, chill, and top with cream and chocolate before serving.\"],\"yield\":\"\",\"groups\":[],\"times\":[0,0,0]}": "6a20739e0c56359486696473",
  "{\"name\":\"peruvian inspired chicken w/coconut rice\",\"ingredients\":[\"6 lb boneless chicken thighs\",\"16 garlic cloves, minced\",\"1⁄2 cup soy sauce\",\"1⁄2 cup fresh lime juice\",\"1⁄4 cup olive oil\",\"1⁄2 cup brown sugar\",\"1⁄4 cup ground cumin\",\"1⁄4 cup smoked paprika\",\"1⁄2 cup dried oregano\",\"Salt and black pepper to taste\",\"3 packed cups fresh cilantro\",\"4-5 fresh jalapeños, seeded and ribs removed\",\"10 garlic cloves\",\"2 cups sour cream\",\"6 scallions, green parts only\",\"3 tbsp lime juice\",\"1⁄2 cup olive oil\",\"5 cups basmati rice, washed, soaked 1 hour, then drained\",\"54 oz coconut milk\",\"4 tsp salt\",\"8-12 corn cobs\",\"Fresh chopped cilantro for garnish\",\"Lime wedges for serving\"],\"instructions\":[\"Mix the chicken with all marinade ingredients and marinate for at least 20 minutes.\",\"Bring rice, coconut milk, and salt to a gentle boil. Cover and cook on low for 12-15 minutes. Let steam, covered, for 10 minutes, then fluff.\",\"Blend all aji verde ingredients until smooth and creamy.\",\"Sear or grill chicken until golden and cooked through.\",\"Serve chicken over coconut rice with aji verde, corn, cilantro, and lime.\"],\"yield\":\"\",\"groups\":[],\"times\":[30,30,60]}": "6a2ee3f6a60f749e8436af75",
  "{\"name\":\"slow cooker white chicken chili\",\"ingredients\":[\"1 1/2 pounds boneless, skinless chicken thighs\",\"4 cups chicken stock\",\"3 (4-ounce) cans diced green chiles\",\"1 (15.5 ounce) can cannellini beans (drained and rinsed)\",\"1 (15.5 ounce) can garbanzo beans (drained and rinsed)\",\"1 medium sweet onion (diced)\",\"4 cloves garlic (minced)\",\"1 teaspoon ground cumin\",\"1 teaspoon dried oregano\",\"Kosher salt and freshly ground black pepper (to taste)\",\"1/2 cup chopped fresh cilantro leaves\",\"2 tablespoons freshly squeezed lime juice\",\"1 1/2 cups tortilla chips\",\"1/2 cup fresh cilantro leaves\",\"1/2 cup sour cream\",\"1/2 cup diced red onion\",\"1 avocado (halved, seeded, peeled and sliced)\",\"1 lime (cut into wedges)\"],\"instructions\":[\"Place chicken into a 6-qt slow cooker. Stir in chicken stock, green chiles, beans, onion, garlic, cumin and oregano; season with salt and pepper, to taste.\",\"Cover and cook on low heat for 7-8 hours or high heat for 5-6 hours.\",\"Remove chicken from the slow cooker and shred, using two forks.\",\"Stir chicken, cilantro and lime juice into the slow cooker; season with salt and pepper, to taste.\",\"Serve immediately with desired toppings.\"],\"yield\":\"6\",\"groups\":[],\"times\":[20,480,500]}": "6a369fd048d379e4c7572c8c",
  "{\"name\":\"pizza dough\",\"ingredients\":[\"7g yeast (2 1/4 tsp)\",\"4 tbsp flour\",\"1 tsp sugar\",\"200g water\",\"1.5kg flour\",\"600g water\",\"300g ice\",\"26g olive oil\",\"26g salt\",\"18g vegetable oil\"],\"instructions\":[\"Combine the initial yeast, 4 tablespoons flour, 1 teaspoon sugar, and 200g water mixture.\",\"In a larger mixing container, incorporate the 1.5kg of flour, 600g water, 300g ice, 26g olive oil, 26g salt, and 18g vegetable oil.\",\"Thoroughly mix all ingredients until a cohesive dough forms.\",\"Knead the dough until smooth and elastic, then proceed with proofing.\"],\"yield\":\"\",\"groups\":[],\"times\":[0,0,0]}": "6a3808aea60f749e8436c508",
  "{\"name\":\"nashville hot chicken\",\"ingredients\":[\"4 boneless, skinless chicken thighs\",\"1 cup buttermilk (You can make your own buttermilk by adding 1 Tbsp of lemon juice or vinegar to a cup of milk)\",\"1/4 cup pickle juice\",\"1/4 cup hot sauce\",\"1 cup all-purpose flour\",\"1/4 cup cornstarch\",\"1 tsp baking powder\",\"2 Tbsp cayenne\",\"1 tsp brown sugar\",\"2 Tbsp paprika\",\"1 Tbsp chili powder\",\"1 Tbsp garlic powder\",\"1/2 tsp freshly cracked black pepper\",\"1 tsp salt\",\"4 pieces of Texas toast\",\"8 pickle chips\"],\"instructions\":[\"Combine the buttermilk, pickle juice, and hot sauce in a bowl and soak the chicken thighs in the mixture.\",\"Whisk together the flour, cornstarch, baking powder, and a portion of the salt in a shallow dish.\",\"Dredge the soaked chicken thighs into the flour mixture, ensuring they are well coated.\",\"Heat the vegetable oil in a pan and fry the chicken until golden brown and cooked through.\",\"Mix the cayenne, brown sugar, paprika, chili powder, garlic powder, black pepper, and remaining salt with a small amount of hot frying oil to create the spice coating.\",\"Brush or coat the fried chicken with the spicy seasoning mixture.\",\"Serve the Nashville hot chicken on thick slices of Texas bread topped with pickle chips.\"],\"yield\":\"Serves 4\",\"groups\":[[\"MARINADe\",1],[\"COATING\",4],[\"SAUce\",7],[\"SERVE WITh\",14]],\"times\":[70,10,80]}": "6a3ea8302a814c568b6ac6a2",
  "{\"name\":\"chef's fridge pickles\",\"ingredients\":[\"2 cucumbers, sliced into 3–5 mm rounds (or spears)\",\"1 small red onion, thinly sliced\",\"2 cloves garlic, lightly crushed\",\"Optional vegetables: carrots, radishes, green beans, cauliflower, jalapeños, or cabbage\",\"500 ml white vinegar (5% acidity)\",\"500 ml water\",\"40 g fine sea salt (about 2 tbsp)\",\"50 g white sugar (about 1⁄4 cup)\",\"1 tsp black peppercorns per jar\",\"1 tsp mustard seeds per jar\",\"1⁄2 tsp coriander seeds per jar\",\"1 bay leaf per jar\",\"2–3 sprigs fresh dill per jar\",\"Optional: 1⁄4 tsp chili flakes per jar\"],\"instructions\":[\"Wash your jars thoroughly.\",\"Pack the vegetables tightly into the jars with the garlic, dill, bay leaf, peppercorns, mustard seeds, coriander seeds, and any chili flakes.\",\"Combine the vinegar, water, salt, and sugar in a saucepan and bring just to a simmer, stirring until the salt and sugar have dissolved.\",\"Let the brine cool down to luke warm, then carefully pour over the vegetables until fully submerged, leaving about 1 cm of headspace.\",\"Allow the jars to cool to room temperature before sealing.\",\"Refrigerate for at least 24 hours before serving.\"],\"yield\":\"2 × 500 ml jars\",\"groups\":[[\"VEGETables\",0],[\"BRINe\",4]],\"times\":[15,5,20]}": "6a4c9784861f2ce11c7999ec",
  "{\"name\":\"baked zucchini chips\",\"ingredients\":[\"2 zucchinis (thinly sliced to 1/4-inch thick rounds)\",\"1/2 teaspoon garlic powder\",\"1/4 cup milk\",\"1 large egg\",\"Kosher salt and freshly ground black pepper\",\"1 1/2 cups finely crushed Kettle Brand® Himalayan Salt Potato Chips\",\"1/2 cup all-purpose flour\",\"2 tablespoons chopped fresh parsley leaves\"],\"instructions\":[\"Preheat oven to 425 degrees F. Lightly oil a baking sheet or coat with nonstick spray.\",\"Season zucchini with garlic powder, salt and pepper, to taste.\",\"In a medium bowl, combine milk and egg; set aside.\",\"Working in batches, dredge zucchini rounds in flour, dip into the milk mixture, then dredge in crushed potato chips, pressing to coat. Place zucchini rounds in a single layer onto the prepared baking sheet; coat with nonstick spray.\",\"Place into oven and bake golden brown and crisp, about 22-26 minutes.\",\"Serve immediately, garnished with parsley, if desired.\"],\"yield\":\"8\",\"groups\":[],\"times\":[20,25,45]}": "6a49847a861f2ce11c7996dd",
  "{\"name\":\"s'mores pudding cake\",\"ingredients\":[\"2 cups graham cracker crumbs\",\"8 Tablespoons unsalted butter, melted\",\"1 box chocolate cake mix\",\"1 cup miniature marshmallows\",\"1 (3.9 ounce) box instant chocolate pudding\",\"2 cups milk\",\"1 (8 ounce) container Cool Whip, thawed\",\"1 (7 ounce) jar marshmallow cream\",\"3 full size Hershey chocolate bars, chopped\",\"1 cup graham cracker chunks\"],\"instructions\":[\"Preheat the oven to 350 degrees. Spray a 9x13 pan with nonstick baking spray.\",\"Combine the graham cracker crumbs and melted butter. Press into the bottom of the prepared pan.\",\"Prepare the cake mix according to the box directions. Spoon the batter on top of the prepared crust.\",\"Bake for 28 minutes or until a toothpick inserted in the center comes out clean. Let the cake cool for 10 minutes.\",\"Use the handle of a wooden spoon to gently poke holes all over the top of the cake.\",\"Whisk together the pudding mix and milk. Pour over the top of the warm cake, trying to get the pudding in the holes. Smooth with a spoon and tap the pan on the counter to help the pudding settle.\",\"Cool for 30 minutes on the counter, then refrigerate until chilled all the way through.\",\"Stir together the thawed Cool Whip and marshmallow cream gently. Spread over the cooled cake.\",\"Top with the chopped chocolate bars, graham cracker chunks, and marshmallows.\",\"Store in a sealed container in the refrigerator.\"],\"yield\":\"24 pieces\",\"groups\":[],\"times\":[20,28,48]}": "6a53cc7f861f2ce11c79a238",
  "{\"name\":\"honey garlic steak bites & crispy potatoes\",\"ingredients\":[\"1 lb Steak, cubed\",\"1 lb Potatoes, halved or quartered\",\"4 cloves Garlic, minced\",\"1/3 cup Honey\",\"2 tbsp Soy Sauce\",\"1 tbsp Olive Oil\",\"Salt and Pepper, to taste\",\"Parsley, for garnish\"],\"instructions\":[\"Season the steak and potatoes.\",\"Roast the potatoes until crispy (approximately 20 minutes).\",\"Sear the steak bites in a skillet for a few minutes per side.\",\"Add the minced garlic, honey, and soy sauce to the skillet and toss to coat the steak.\"],\"yield\":\"Serves 4\",\"groups\":[],\"times\":[10,20,30]}": "6a540ffd861f2ce11c79a2b2",
  "{\"name\":\"white bean stew\",\"ingredients\":[\"4 tablespoons olive oil\",\"1 onion, diced\",\"3 garlic cloves, minced\",\"2 celery stalks, diced\",\"1 teaspoon dried rosemary\",\"1/2 teaspoon smoked paprika\",\"1 pinch chilli flakes\",\"2 cans white beans, drained\",\"1 28oz can crushed tomatoes\",\"1 cup vegetable broth\",\"Handful of fresh spinach\",\"Lemon juice (to taste)\",\"Extra olive oil for drizzling\"],\"instructions\":[\"Sauté the onion, garlic, and celery in four tablespoons of olive oil for eight minutes until soft.\",\"Add the rosemary, smoked paprika, and chilli flakes; cook the spices for sixty seconds.\",\"Add the drained white beans, crushed tomatoes, and vegetable broth.\",\"Stir everything together and bring to a gentle simmer; avoid boiling aggressively to maintain the bean texture.\",\"Simmer uncovered for twenty minutes until the stew thickens and the beans break down slightly to create a rich consistency.\",\"Stir in the fresh spinach until just wilted.\",\"Finish with a squeeze of lemon juice and a generous drizzle of olive oil before serving.\"],\"yield\":\"4\",\"groups\":[],\"times\":[0,0,0]}": "6a64d261d73f69ae6d182e35",
  "{\"name\":\"aloo tikki\",\"ingredients\":[\"600g/1lb 5oz potatoes, peeled and cut into chunks\",\"11⁄2 tsp salt\",\"4 spring onions, white and green parts finely chopped\",\"2–3 small chillies (bird’s eye or similar), finely chopped, seeds in\",\"handful fresh coriander, finely chopped\",\"2 tsp ground coriander\",\"1 tsp cumin seeds, toasted and crushed\",\"1 tsp ginger powder\",\"3 tbsp panko breadcrumbs or any other breadcrumbs\",\"sunflower oil, for shallow frying\",\"tomato ketchup or tamarind chutney, to serve (optional)\",\"4 tsp sunflower oil\",\"1 tsp cumin seeds\",\"2 tsp finely grated fresh root ginger\",\"1 tsp red chilli powder\",\"1⁄2 tsp ground turmeric\",\"1 tsp salt\",\"2 tsp ground coriander\",\"5 tsp tomato purée\",\"300g/101⁄2oz tinned chickpeas, drained and rinsed\",\"handful fresh coriander\"],\"instructions\":[\"To make the aloo tikki, place the potatoes in a saucepan of water, add 1⁄2 tsp salt and bring to the boil. Boil until the potatoes are soft, then drain immediately. Transfer to a large bowl and leave to cool down. Add the rest of the ingredients (except the oil), mash together with the potatoes and mix so everything is well coated. Divide the mixture into 12 equal balls, then press and flatten each one.\",\"Meanwhile, make the chickpeas. Heat the oil in a saucepan over a medium heat. Add the cumin seeds and, as soon they start to sizzle, add the ginger and cook for 1 minute. Add the chilli powder, turmeric, salt, coriander, tomato purée and 100ml/31⁄2fl oz water and mix well. Add the chickpeas and cook over a medium heat for 4–5 minutes. Stir occasionally and check they don’t stick to the bottom of the pan.\",\"To cook the aloo tikki, heat about 2 teaspoons sunflower oil in a frying pan. Once hot, turn the heat to medium and cook the tikki in batches, cooking on each side for about 3 minutes, until golden brown and crisp. Serve hot with the chickpeas and tomato ketchup or tamarind chutney.\"],\"yield\":\"Serves 4\",\"groups\":[],\"times\":[30,30,60]}": "6a65a81e48d379e4c757d756",
  "{\"name\":\"roasted tomato soup\",\"ingredients\":[\"3-4 large tomatoes\",\"1 large onion\",\"2-3 kapia peppers (or red bell peppers)\",\"1 head of garlic\",\"1 tablespoon butter\",\"1 tablespoon flour\",\"1 cup milk\",\"2 cups water\",\"1 teaspoon salt\",\"1 teaspoon red pepper powder (paprika)\",\"Olive oil\"],\"instructions\":[\"Arrange the tomatoes, onion, peppers, and garlic on a baking tray.\",\"Drizzle with olive oil and roast in a preheated oven at 200°C (392°F) with the fan setting until well roasted.\",\"Peel the skins off the roasted vegetables and blend them until smooth.\",\"In a pot, sauté the butter and flour until fragrant.\",\"Add the blended tomato mixture, water, salt, and red pepper powder; boil for approximately 5 minutes.\",\"Finally, add the milk and boil for another 2-3 minutes, then serve hot.\"],\"yield\":\"\",\"groups\":[],\"times\":[0,0,0]}": "6a68690d52f5f0af4a90f2ff",
  "{\"name\":\"cheesy ground chicken fajita pasta\",\"ingredients\":[\"1 tablespoon oil\",\"1 pound ground chicken (turkey)\",\"1 onion, sliced or diced\",\"1 green bell pepper, sliced or diced\",\"1 red bell pepper, sliced or diced\",\"1 yellow bell pepper, sliced or diced\",\"3 cloves garlic, chopped\",\"2 tablespoons taco seasoning\",\"2 1/2 cups chicken broth\",\"1 (15 ounce) can diced tomatoes\",\"8 ounces pasta\",\"1/2 cup sour cream (or heavy cream, or 4 ounces cream cheese) (optional)\",\"2 cup cheddar cheese (or monetary jack), shredded\",\"1 tablespoon cilantro, chopped\"],\"instructions\":[\"Heat the oil in a large pan over medium heat, add the chicken and cook, breaking it apart as it cooks, for 5 minutes.\",\"Add the onion and bell peppers and cook until tender, about 10 minutes.\",\"Add the garlic and taco seasoning and cook until fragrant, about a minute.\",\"Add the broth, tomatoes, and pasta, bring to a boil, reduce the heat and simmer until the pasta is tender, about 8-10 minutes, mixing every few minutes.\",\"Mix in the sour cream and half of the cheese and let it melt into the sauce.\",\"Sprinkle on the remaining cheese and let it melt (cover with a lid for 2-3 minutes or broil).\"],\"yield\":\"4 servings\",\"groups\":[],\"times\":[10,30,40]}": "6a68957d48d379e4c757de5b",
  "{\"name\":\"caramel apple cheesecake bars\",\"ingredients\":[\"1 1/2 cups graham cracker crumbs\",\"1/3 cup brown sugar\",\"1/2 cup melted butter\",\"16 oz cream cheese, softened\",\"1/2 cup granulated sugar\",\"1 tsp vanilla extract\",\"2 large eggs\",\"3 cups peeled & diced apples\",\"1/4 cup brown sugar\",\"1 tsp cinnamon\",\"1 tbsp lemon juice\",\"1/2 cup all-purpose flour\",\"1/3 cup brown sugar\",\"1/2 tsp cinnamon\",\"1/4 cup cold butter, cubed\",\"1/3 cup old-fashioned oats\"],\"instructions\":[\"Preheat oven to 350°F (175°C). Line an 8x8-inch pan with parchment paper.\",\"Make crust: Mix graham cracker crumbs, brown sugar and melted butter. Press firmly into pan. Bake 8 minutes. Cool slightly.\",\"Make cheesecake layer: Beat cream cheese, sugar and vanilla until smooth. Add eggs one at a time. Pour over crust; spread evenly.\",\"Make apple filling: In a skillet, cook apples, brown sugar, cinnamon and lemon juice over medium heat until tender, about 6-8 minutes. Let cool slightly, then spoon over cheesecake layer.\",\"Make streusel: Mix flour, brown sugar and cinnamon. Cut in cold butter until crumbly. Stir in oats. Sprinkle over apples.\",\"Bake 40-45 minutes, until set and golden on top. Cool completely, then chill at least 2 hours before slicing. Drizzle with caramel if desired.\"],\"yield\":\"16 bars\",\"groups\":[[\"Graham cracker crust\",0],[\"Cheesecake layer\",3],[\"Apple filling\",7],[\"Streusel topping\",11]],\"times\":[0,0,0]}": "6a7f7a14617ae028323946ba",
  "{\"name\":\"brown butter pumpkin chocolate chip cookies\",\"ingredients\":[\"1 cup (2 sticks) unsalted butter\",\"1 cup packed brown sugar\",\"1/2 cup granulated sugar\",\"1 cup canned pumpkin puree\",\"1 large egg + 1 egg yolk\",\"2 tsp vanilla extract\",\"2 1/2 cups all-purpose flour\",\"1 tsp baking soda\",\"1 tsp baking powder\",\"1 1/2 tsp pumpkin pie spice\",\"1/2 tsp salt\",\"2 cups semi-sweet chocolate chips\",\"1/2 cup chopped dark chocolate (optional)\"],\"instructions\":[\"BROWN THE BUTTER: Melt butter in a saucepan over medium heat, stirring often, until golden brown and nutty. Remove from heat and cool 10 minutes.\",\"MIX WET: Whisk brown sugar, granulated sugar, and cooled brown butter. Add pumpkin, egg, egg yolk, and vanilla; mix until smooth.\",\"MIX DRY: In a separate bowl, whisk flour, baking soda, baking powder, pumpkin pie spice, and salt.\",\"COMBINE: Add dry ingredients to wet ingredients and mix just until combined. Fold in chocolate chips and chopped chocolate if using.\",\"CHILL: Cover dough and chill for 30 minutes. This helps the cookies stay thick and chewy.\",\"BAKE: Scoop 2-tbsp portions onto a parchment-lined baking sheet. Bake at 350°F (175°C) for 12-14 minutes, until edges are set and centers look soft. Cool on the pan 5 minutes, then transfer to a wire rack.\"],\"yield\":\"24 cookies\",\"groups\":[],\"times\":[0,0,0]}": "6a7f7c46617ae028323946d5",
  "{\"name\":\"pumpkin french toast with spiced pecan syrup\",\"ingredients\":[\"3 large eggs\",\"1/2 cup half & half (or whole milk)\",\"1/2 cup pumpkin puree\",\"1 Tablespoon maple syrup\",\"1 teaspoon pure vanilla extract\",\"1 teaspoon pumpkin spice\",\"1⁄2 teaspoon cinnamon\",\"1 (14 oz) loaf brioche bread (sliced into 1⁄2” slices)\",\"2-4 Tablespoons butter (for pan)\",\"1 cup maple syrup\",\"2 tbsp water\",\"1 cinnamon stick\",\"4 whole cloves\",\"1⁄8 tsp ground nutmeg\",\"4 oz about 1 cup halved pecans\"],\"instructions\":[\"In a large shallow bowl, beat the eggs, half & half, pumpkin, maple syrup, vanilla, pumpkin spice, and cinnamon until smooth and well combined.\",\"Heat a griddle over medium heat. Add the butter, swirling it around to melt over the entire griddle. Working in batches, submerge the slices of brioche bread into the egg mixture for about 10 seconds each.\",\"Place the bread onto the hot greased skillet. Cook until golden brown, about 3-4 minutes per side or until golden crispy and cooked through.\",\"Serve the French toast with extra butter, pecan maple syrup, and a drizzle of cinnamon.\",\"Spiced Pecan Syrup: Add the maple syrup, water, cinnamon stick, cloves, and nutmeg to a small saucepan; whisk to combine. Bring the syrup to a simmer, reduce the heat to low, and simmer for 10-12 minutes. Remove the cinnamon stick and cloves. Stir in the pecans. Serve warm.\"],\"yield\":\"12\",\"groups\":[],\"times\":[10,10,20]}": "6a98394b9262720e79407bc4",
  "{\"name\":\"french onion meatballs with mashed potatoes\",\"ingredients\":[\"1 lb ground beef\",\"1/2 cup breadcrumbs\",\"1/4 cup grated Parmesan\",\"1 large egg\",\"2 cloves garlic, minced\",\"1 tsp Worcestershire sauce\",\"1/2 tsp salt\",\"1/4 tsp black pepper\",\"2 tbsp olive oil\",\"3 large onions, thinly sliced\",\"1 tsp sugar\",\"1/2 tsp salt\",\"1/4 tsp black pepper\",\"2 cloves garlic, minced\",\"1 tbsp flour\",\"2 cups beef broth\",\"1 tbsp Worcestershire sauce\",\"1 tsp fresh thyme (or 1/2 tsp dried)\",\"1 bay leaf\",\"2 lbs Yukon Gold potatoes, peeled & cubed\",\"4 tbsp butter\",\"1/2 cup milk or heavy cream\",\"1/2 tsp salt\",\"1/4 tsp black pepper\"],\"instructions\":[\"Mix meatball ingredients in a bowl, roll into 1-inch balls.\",\"Heat skillet with oil, sear meatballs in batches until browned, then remove.\",\"In the same skillet, heat olive oil and cook onions with sugar, salt, and pepper for 20-25 minutes until caramelized.\",\"Stir in garlic for 1 minute, then add flour to coat.\",\"Whisk in beef broth, Worcestershire sauce, thyme, and bay leaf; bring to a simmer.\",\"Return meatballs to the skillet, cover, and simmer on low for 15-20 minutes.\",\"Boil potatoes in salted water for 12-15 minutes, drain, and mash with butter, milk, salt, and pepper.\",\"Serve meatballs and gravy over mashed potatoes.\"],\"yield\":\"4-6 servings\",\"groups\":[],\"times\":[20,40,60]}": "6a9b9fda02818e56c16fe741",
  "{\"name\":\"maple pecan pie bars\",\"ingredients\":[\"1 1/2 cups all-purpose flour\",\"1/2 cup powdered sugar\",\"3/4 cup cold butter, cubed\",\"1/4 tsp salt (for crust)\",\"1/2 cup unsalted butter, melted\",\"3/4 cup brown sugar\",\"1/2 cup pure maple syrup\",\"2 large eggs\",\"1 tsp vanilla extract\",\"1 tbsp all-purpose flour (for filling)\",\"1/4 tsp salt (for filling)\",\"2 cups pecan halves\",\"1/2 cup chopped pecans\"],\"instructions\":[\"Preheat oven to 350°F (175°C) and line an 8x8-inch pan with parchment paper.\",\"Pulse 1 1/2 cups flour, powdered sugar, cold butter, and salt in a food processor until crumbly. Press into prepared pan and bake 15 minutes.\",\"In a large bowl, whisk together melted butter, brown sugar, maple syrup, eggs, vanilla, 1 tbsp flour, and salt until smooth.\",\"Stir in pecan halves and chopped pecans.\",\"Pour filling over the warm crust and spread evenly.\",\"Bake 20-25 minutes, until set, glossy, and the top is golden.\",\"Cool completely, then chill for at least 2 hours before slicing into bars.\"],\"yield\":\"16 bars\",\"groups\":[],\"times\":[20,35,55]}": "6a9c4acb02818e56c16fe77b",
  "{\"name\":\"chicken stir fry with rice noodles\",\"ingredients\":[\"150 - 180 g/ 5 - 6 oz chicken breast (, cut into thin strips)\",\"1 tsp cornflour / cornstarch ((optional))\",\"1 tsp oil ((peanut, vegetable, canola) (optional))\",\"2 tbsp oyster sauce ((or sub with Hoisin))\",\"1 tbsp dark soy sauce ((Note 2))\",\"1/2 tsp each sesame oil, sugar ((optional))\",\"1 1/2 tbsp Chinese cooking wine ((Shoaxing wine) OR Mirin (Note 3))\",\"1/4 tsp white pepper ((or black pepper))\",\"3 tbsp water\",\"100 g / 3.5 oz dried rice noodles ((Note 4))\",\"1 tbsp oil\",\"1 garlic clove (, finely chopped (Note 5))\",\"1 small onion (, sliced (white, brown, yellow))\",\"1/2 bunch choy sum or other Asian greens (, stems separated from leaves (Note 6))\",\"1/2 red capsicum / bell pepper (, sliced)\",\"1 carrot (, peeled, cut in half lengthwise and sliced on the diagonal)\",\"5 - 7 mushrooms (, sliced)\",\"Sesame seeds and finely sliced green onions/scallions (, optional)\"],\"instructions\":[\"Mix chicken, cornstarch and oil in a bowl.\",\"Mix Sauce ingredients in a bowl. OR use 3 tbsp Homemade Stir Fry Sauce + 6 tbsp water.\",\"Just before cooking, soak noodles in hot water per packet directions, then drain. (Note 7)\",\"Heat oil in a wok or large skillet over high heat.\",\"Add garlic and onion, cook for 30 seconds.\",\"Add chicken, cook for 1 minute until it changes colour from pink to white.\",\"Add carrot, Choy Sum stems and capsicum. Cook for 1 minute.\",\"Add mushrooms, cook for 30 seconds.\",\"Add noodles, Choy Sum leaves and Sauce. Toss for 1 minute until leaves have wilted and Sauce has evaporated. Don't toss for more then 1 1/2 minutes - noodles may break.\",\"Garnish with sesame seeds and green onions then serve immediately.\"],\"yield\":\"2\",\"groups\":[],\"times\":[10,5,15]}": "6aa5d6629262720e7940a110",
  "{\"name\":\"gluten-free potato doughnuts\",\"ingredients\":[\"60 g instant potato flakes\",\"180 ml boiling water\",\"1 egg\",\"50 g sugar\",\"30 g melted butter\",\"70 g cornstarch\",\"70–100 g rice flour\",\"2 tsp baking powder\",\"1⁄2 tsp salt\",\"vanilla extract\",\"a pinch of nutmeg\",\"cinnamon sugar for coating\"],\"instructions\":[\"Mix the potato flakes with the boiling water and leave for 5 minutes.\",\"Once cooled, mix in the egg, sugar, and melted butter.\",\"Gradually add the dry ingredients until a soft, slightly tacky dough forms.\",\"Chill the dough for 20–30 minutes.\",\"Roll out the dough between two sheets of baking paper to 1.5 cm thickness and cut into doughnut shapes.\",\"Fry at 170–175°C until golden brown.\",\"Coat the doughnuts in cinnamon sugar while still warm.\"],\"yield\":\"\",\"groups\":[],\"times\":[40,10,50]}": "6abdf816388d4deccfa77023",
  "{\"name\":\"caramel apple cinnamon rolls\",\"ingredients\":[\"240 ml warm milk\",\"7 g instant yeast\",\"50 g sugar\",\"1 egg\",\"1 egg yolk\",\"60 g melted butter\",\"420–450 g plain flour\",\"1/2 tsp salt\",\"2 apples, diced\",\"30 g butter\",\"40 g brown sugar\",\"1 tsp cinnamon\",\"Pinch of salt\",\"1 tsp lemon juice\",\"60 g softened butter\",\"100 g brown sugar\",\"2 tsp cinnamon\",\"100 g icing sugar\",\"1–2 tbsp milk\",\"1/2 tsp vanilla extract\",\"100 g sugar\",\"30 g butter\",\"60 ml cream\",\"Pinch of salt\"],\"instructions\":[\"Mix the warm milk, instant yeast, 50 g sugar, egg, egg yolk and melted butter.\",\"Add the flour and salt, then knead until smooth. Cover and let rise for 60–75 minutes.\",\"Cook the diced apples with 30 g butter, 40 g brown sugar, 1 tsp cinnamon, a pinch of salt and lemon juice until tender. Let cool.\",\"Roll the dough into a rectangle. Spread with 60 g softened butter, then sprinkle with 100 g brown sugar and 2 tsp cinnamon.\",\"Spread the cooled apple filling over the dough, roll up and slice into 9 rolls. Arrange in a prepared baking dish.\",\"Let rise for 30–40 minutes, then bake at 180°C for 25–30 minutes.\",\"For the glaze, mix the icing sugar with 1–2 tbsp milk and the vanilla until smooth.\",\"For the caramel, melt the 100 g sugar in a saucepan over medium heat until amber. Carefully stir in the 30 g butter, then slowly add the 60 ml cream; it will bubble vigorously. Stir until smooth, add a pinch of salt and let cool slightly.\",\"Drizzle the glaze and caramel over the warm rolls.\"],\"yield\":\"9 rolls\",\"groups\":[[\"Dough\",0],[\"Apple filling\",8],[\"Cinnamon filling\",14],[\"Vanilla glaze\",17],[\"Caramel sauce\",20]],\"times\":[35,30,65]}": "6ac549861e142fac7ac5f84f",
  "{\"name\":\"pecan pie brownies\",\"ingredients\":[\"170g butter\",\"180g dark chocolate\",\"180g sugar\",\"80g brown sugar\",\"3 eggs\",\"1 tsp vanilla\",\"90g plain flour\",\"30g cocoa powder\",\"1/2 tsp salt\",\"150g pecans, chopped\",\"80g brown sugar (for topping)\",\"60g butter (for topping)\",\"80ml maple syrup\",\"1 egg (for topping)\",\"1/2 tsp vanilla (for topping)\",\"Pinch of salt (for topping)\"],\"instructions\":[\"Preheat oven to 175°C and line a pan.\",\"Melt butter and chocolate together.\",\"Mix in sugars, eggs, and vanilla.\",\"Fold in flour, cocoa powder, and salt.\",\"Spread in pan and bake for 18 minutes.\",\"For the topping, melt butter with brown sugar and syrup, then cool slightly.\",\"Mix in vanilla, salt, egg, and pecans.\",\"Spread over brownie base.\",\"Bake for another 18-22 minutes.\",\"Cool completely before slicing.\"],\"yield\":\"16 brownies\",\"groups\":[],\"times\":[20,40,60]}": "6ac54e6d1e142fac7ac5f88e",
  "{\"name\":\"brown butter maple pecan blondies\",\"ingredients\":[\"170g unsalted butter\",\"180g light brown sugar\",\"40g pure maple syrup\",\"2 large eggs\",\"2 tsp vanilla extract\",\"200g plain (all-purpose) flour\",\"1⁄2 tsp baking powder\",\"1⁄2 tsp fine salt\",\"120g pecans, roughly chopped\",\"100g dark chocolate chips or chunks\",\"60g icing (powdered) sugar\",\"15g pure maple syrup\",\"1–2 tsp milk, as needed\",\"Pinch of salt\"],\"instructions\":[\"Preheat the oven to 175°C / 350°F (160°C fan) and line a 20cm (8-inch) square baking tin with parchment paper.\",\"Brown the butter in a saucepan over medium heat until the milk solids turn golden brown, then pour into a heatproof bowl to cool for 10 minutes.\",\"Toast the pecans on a small baking tray for 5–7 minutes until fragrant and let cool.\",\"Whisk the brown sugar and maple syrup into the cooled browned butter, then add the eggs and vanilla and whisk vigorously for 45 seconds.\",\"Stir together the flour, baking powder, and salt in a separate bowl, then fold into the wet mixture until just combined.\",\"Fold in three-quarters of the pecans and chocolate.\",\"Spread the batter into the prepared tin, scatter the remaining pecans and chocolate on top, and press them in lightly.\",\"Bake for 25–30 minutes until the edges are golden and set.\",\"Cool in the tin for 30 minutes before removing, then finish cooling completely.\",\"Mix the icing sugar, maple syrup, salt, and milk into a thick glaze and drizzle over the blondies before slicing into 16 squares.\"],\"yield\":\"16 squares\",\"groups\":[],\"times\":[20,30,50]}": "6adf911e12ca72bf53933c16",
  "{\"name\":\"white chocolate, cranberry & pistachio cookies\",\"ingredients\":[\"170g unsalted butter, softened\",\"130g light brown sugar\",\"90g caster sugar\",\"Finely grated zest of 1 orange\",\"1 large egg\",\"1 egg yolk\",\"2 tsp vanilla extract\",\"280g plain (all-purpose) flour\",\"1⁄2 tsp bicarbonate of soda (baking soda)\",\"1⁄2 tsp baking powder\",\"1⁄2 tsp fine salt\",\"150g white chocolate chunks or chips\",\"100g dried cranberries\",\"90g shelled pistachios, roughly chopped\",\"Flaky sea salt, optional\"],\"instructions\":[\"Rub the orange zest into the sugars in a large mixing bowl until fragrant.\",\"Cream the butter with the orange sugar for 2–3 minutes until light and fluffy.\",\"Beat in the egg, egg yolk, and vanilla until combined.\",\"Whisk the flour, bicarbonate of soda, baking powder, and salt together in a separate bowl and fold into the butter mixture.\",\"Fold in the white chocolate, dried cranberries, and pistachios, reserving a small amount for the tops.\",\"Divide the dough into 16 portions, roll into chunky balls, press the reserved mix-ins onto the tops, and refrigerate for at least 30 minutes.\",\"Preheat the oven to 180°C / 350°F (160°C fan) and line two baking trays.\",\"Bake for 12–15 minutes until the edges are golden and the centers remain slightly soft.\",\"Let the cookies set on the trays for 10 minutes before transferring to a wire rack, finishing with a sprinkle of flaky salt if desired.\"],\"yield\":\"16 cookies\",\"groups\":[],\"times\":[50,15,65]}": "6adf946812ca72bf53933d3c",
  "{\"name\":\"the christmas dinner pie\",\"ingredients\":[\"350g plain (all-purpose) flour\",\"175g cold unsalted butter, cubed\",\"1⁄2 tsp fine salt\",\"5–7 tbsp ice-cold water\",\"600g cooked turkey, roughly chopped or shredded\",\"40g butter\",\"1 large onion, finely diced\",\"1 medium leek, sliced\",\"2 garlic cloves, minced\",\"40g plain flour\",\"450ml turkey or chicken stock\",\"1 tsp Dijon or English mustard\",\"1 tsp Worcestershire sauce\",\"1 tsp fresh thyme leaves (or 1⁄2 tsp dried)\",\"1⁄2 tsp dried sage\",\"Salt and black pepper, to taste\",\"200g slightly stale bread, cut into small cubes or coarse breadcrumbs\",\"1 medium onion, finely diced\",\"50g butter\",\"2 tsp dried sage (or 1 tbsp finely chopped fresh sage)\",\"1 egg, lightly beaten\",\"150–200ml warm chicken or vegetable stock\",\"2 egg yolks\",\"Red and green food colouring\"],\"instructions\":[\"Rub cold butter into the flour and salt, add water, shape into a disc, and chill for 30 minutes.\",\"Sauté onion and leek in butter, stir in garlic and flour, then add stock, mustard, Worcestershire sauce, and herbs to create a thick gravy. Fold in turkey and cool completely.\",\"Roll out pastry to line a 23cm pie tin, prick base, and blind-bake at 200°C for 15-25 minutes until dry.\",\"Cook onion in butter for the stuffing, mix with breadcrumbs, herbs, egg, and stock. Let stand for 10-15 minutes.\",\"Roll the stuffing between baking paper into a circular sheet and refrigerate for 20 minutes.\",\"Spoon cold turkey filling into the pastry case, invert the stuffing lid on top, and press down to seal.\",\"Trim pastry edges, fold and crimp decoratively. Paint sections of the crimp with red and green dyed egg yolks.\",\"Reduce oven to 190°C and bake for 45–55 minutes until the stuffing is golden brown and bubbling.\",\"Let rest for 15-20 minutes before serving.\"],\"yield\":\"Serves 6–8\",\"groups\":[],\"times\":[70,80,150]}": "6adf98c012ca72bf53933e0b"
}
